74	/// `Some(exit code)` when `key` quits. `r` doesn't force a re-extraction — past its first call `initialize()` just returns
75	/// the current snapshot — but it still refreshes the tracked exit code, as an automatic reload does.
76	fn handle_key(key: KeyCode, session: &WatchSession, exit_code: &AtomicI32) -> Option<i32> {
77	    match key {
78	        KeyCode::Char('q') | KeyCode::Char('c') => Some(exit_code.load(Ordering::Relaxed)),
79	        KeyCode::Char('r') => {
80	            exit_code.store(watch_exit_code(&session.initialize()), Ordering::Relaxed);
81	            None
82	        }
83	        _ => None,
84	    }
85	}
