87	fn spawn_keyboard_thread(session: Arc<WatchSession>, exit_code: Arc<AtomicI32>, running: Arc<AtomicBool>) {
88	    std::thread::spawn(move || {
89	        use crossterm::event::{self, Event};
90	        let _ = crossterm::terminal::enable_raw_mode();
91	        while running.load(Ordering::Relaxed) {
92	            if let Ok(Event::Key(key)) = event::read() {
93	                if let Some(code) = handle_key(key.code, &session, &exit_code) {
94	                    let _ = crossterm::terminal::disable_raw_mode();
95	                    // watchexec has no graceful-quit handle reachable from this thread, so this hard-exits, with the
96	                    // tracked code so a session that quit on an unresolved error still fails the shell.
97	                    std::process::exit(code);
98	                }
99	            }
100	        }
101	        let _ = crossterm::terminal::disable_raw_mode();
102	    });
103	}
