105	/// Returns the diagnostic to report when the snapshot can't be written to `path`.
106	fn write_snapshot(path: &str, snapshot: &ExtractionOutput) -> Option<Diagnostic> {
107	    let json = serde_json::to_string(snapshot).ok()?;
108	    let error = write_atomic(path, &json).err()?;
109	    Some(Diagnostic {
110	        severity: DiagnosticSeverity::Error,
111	        message: format!("Failed to write '{path}': {error}"),
112	        file: Some(path.to_owned()),
113	        line: None,
114	        column: None,
115	        help: Some("Check that the output path's parent directory exists and is writable.".into()),
116	        code: DiagnosticCode::IoError,
117	    })
118	}
