120	/// The console line for a re-resolved file: its name and the components it re-resolved, or none if it re-resolved none.
121	fn update_line(path: &camino::Utf8Path, component_names: &[&str]) -> Option<String> {
122	    use owo_colors::OwoColorize;
123	    if component_names.is_empty() {
124	        return None;
125	    }
126	    Some(format!("  {}  {}", path.file_name().unwrap_or("?").dimmed(), component_names.join(", ").bold()))
127	}
