129	/// One file-change event: re-resolves `path` if it is TypeScript, tracks the exit code, prints the delta, rewrites `--out`.
130	fn handle_change(session: &WatchSession, path: &Path, quiet: bool, out: Option<&str>, exit_code: &AtomicI32) {
131	    if !matches!(path.extension().and_then(|e| e.to_str()), Some("ts" | "tsx")) {
132	        return;
133	    }
134	    let Ok(path) = camino::Utf8PathBuf::from_path_buf(path.to_owned()) else { return };
135	
136	    let update = session.update_file(&path);
137	    // The cumulative snapshot, not this event's delta: a clean update to one file must not reset the exit code while
138	    // an earlier file in the session still has an unresolved error.
139	    let snapshot = session.snapshot();
140	    exit_code.store(watch_exit_code(&snapshot), Ordering::Relaxed);
141	
142	    if !quiet {
143	        let names: Vec<_> = update.updated_components.iter().map(|c| c.display_name.as_str()).collect();
144	        if let Some(line) = update_line(&path, &names) {
145	            println!("{line}");
146	        }
147	        print_diagnostics(&update.diagnostics);
148	    }
149	    if let Some(failure) = out.and_then(|out| write_snapshot(out, &snapshot)) {
150	        print_diagnostics(&[failure]);
151	    }
152	}
