154	pub fn cmd_watch(args: crate::WatchArgs, quiet: bool, config_path: Option<&str>) -> Result<i32> {
155	    let (options, session, exit_code) = start_session(&args, quiet, config_path)?;
156	
157	    let running = Arc::new(AtomicBool::new(true));
158	    spawn_keyboard_thread(session.clone(), exit_code.clone(), running.clone());
159	
160	    // watchexec's constructor is synchronous even though its event loop is async.
161	    let src_dirs: Vec<std::path::PathBuf> = options.src_dirs.iter().map(|p| p.as_std_path().to_owned()).collect();
162	
163	    let rt = tokio::runtime::Runtime::new().into_diagnostic()?;
164	    let handler_exit_code = exit_code.clone();
165	    rt.block_on(async move {
166	        use watchexec::Watchexec;
167	
168	        let wx = Watchexec::new(move |action| {
169	            for event in action.events.iter() {
170	                for (path, _) in event.paths() {
171	                    handle_change(&session, path, quiet, args.out.as_deref(), &handler_exit_code);
172	                }
173	            }
174	            action
175	        })
176	        .into_diagnostic()?;
177	
178	        wx.config.pathset(src_dirs);
179	        wx.main().await.into_diagnostic()??;
180	        Ok::<(), miette::Error>(())
181	    })?;
182	
183	    running.store(false, Ordering::Relaxed);
184	    Ok(exit_code.load(Ordering::Relaxed))
185	}
