1	/// Writes `contents` to `path` via a same-directory temp file + rename, so a
2	/// mid-write failure (disk full, permission revoked) can never leave `path`
3	/// truncated or half-written. Returns the `io::Error` on failure instead of
4	/// swallowing it — callers must report it, not discard the `Result`.
5	pub fn write_atomic(path: &str, contents: &str) -> std::io::Result<()> {
6	    let target = std::path::Path::new(path);
7	    let dir = parent_dir(target);
8	    let file_name = target.file_name().ok_or_else(|| {
9	        std::io::Error::new(std::io::ErrorKind::InvalidInput, format!("'{path}' has no file name component"))
10	    })?;
11	    let mut tmp_name = std::ffi::OsString::from(".");
12	    tmp_name.push(file_name);
13	    tmp_name.push(".tmp");
14	    let tmp_path = dir.join(tmp_name);
15	    if let Err(e) = std::fs::write(&tmp_path, contents) {
16	        let _ = std::fs::remove_file(&tmp_path);
17	        return Err(e);
18	    }
19	    if let Err(e) = std::fs::rename(&tmp_path, target) {
20	        let _ = std::fs::remove_file(&tmp_path);
21	        return Err(e);
22	    }
23	    Ok(())
24	}
