26	/// The directory holding `target`; a bare file name lives in the current directory.
27	fn parent_dir(target: &std::path::Path) -> &std::path::Path {
28	    match target.parent() {
29	        Some(p) if !p.as_os_str().is_empty() => p,
30	        _ => std::path::Path::new("."),
31	    }
32	}
