91	/// The text between the first pair of single quotes in `message`, e.g. `Date` from
92	/// `"Cannot resolve type 'Date' in 'a.ts'"`. Falls back to the full message when there's
93	/// no quoted substring, so unrelated diagnostics never collide on an empty subject.
94	fn extract_subject(message: &str) -> &str {
95	    let Some(start) = message.find('\'') else {
96	        return message;
97	    };
98	    let rest = &message[start + 1..];
99	    match rest.find('\'') {
100	        Some(len) => &rest[..len],
101	        None => message,
102	    }
103	}
104	
105	/// One or more diagnostics collapsed into a single reported group, keyed by `(code, subject)`.
106	struct DiagnosticGroup<'a> {
107	    representative: &'a oxc_react_docgen_core::types::Diagnostic,
108	    count: usize,
109	    files_seen: Vec<Option<&'a str>>,
110	}
111	
112	/// Collapses near-duplicate diagnostics (same code + same quoted subject) into groups, so a
113	/// single root cause that produced hundreds of diagnostics reports as one line with a count
114	/// instead of flooding the terminal. Order is preserved as first-seen, per group.
115	fn group_diagnostics(diagnostics: &[oxc_react_docgen_core::types::Diagnostic]) -> Vec<DiagnosticGroup<'_>> {
116	    let mut groups: Vec<(&oxc_react_docgen_core::types::DiagnosticCode, &str, DiagnosticGroup)> = Vec::new();
117	    for d in diagnostics {
118	        let subject = extract_subject(&d.message);
119	        match groups.iter_mut().find(|(code, s, _)| *code == &d.code && *s == subject) {
120	            Some((_, _, group)) => {
121	                group.count += 1;
122	                if !group.files_seen.contains(&d.file.as_deref()) {
123	                    group.files_seen.push(d.file.as_deref());
124	                }
125	            }
126	            None => groups.push((
127	                &d.code,
128	                subject,
129	                DiagnosticGroup { representative: d, count: 1, files_seen: vec![d.file.as_deref()] },
130	            )),
131	        }
132	    }
133	    let mut groups: Vec<DiagnosticGroup> = groups.into_iter().map(|(_, _, group)| group).collect();
134	    groups.sort_by_key(|group| std::cmp::Reverse(group.count));
135	    groups
136	}
137	
138	/// Formats grouped diagnostics into the lines `print_diagnostics` writes to stderr. Pulled out
139	/// as a pure function so grouping/formatting behavior is unit-testable without capturing stderr.
140	fn format_diagnostics(diagnostics: &[oxc_react_docgen_core::types::Diagnostic]) -> Vec<String> {
141	    use owo_colors::OwoColorize;
142	
143	    let mut lines = Vec::new();
144	    for group in group_diagnostics(diagnostics) {
145	        let d = group.representative;
146	        let prefix = match d.severity {
147	            oxc_react_docgen_core::types::DiagnosticSeverity::Error => "error".red().to_string(),
148	            oxc_react_docgen_core::types::DiagnosticSeverity::Warning => "warn".yellow().to_string(),
149	            oxc_react_docgen_core::types::DiagnosticSeverity::Info => "info".dimmed().to_string(),
150	            _ => "info".dimmed().to_string(),
151	        };
152	
153	        let suffix = match (group.count, group.files_seen.len()) {
154	            (1, _) => String::new(),
155	            (count, 1) => format!("  (×{count})"),
156	            (count, files) => format!("  (×{count}, {files} files)"),
157	        };
158	
159	        if let Some(ref file) = d.file {
160	            lines.push(format!("  [{prefix}] {file}:{}{suffix}", d.message));
161	        } else {
162	            lines.push(format!("  [{prefix}] {}{suffix}", d.message));
163	        }
164	        if let Some(ref help) = d.help {
165	            lines.push(format!("    {} {}", "help:".dimmed(), help));
166	        }
167	    }
168	    lines
169	}
