171	/// The `inspect` view of one component: header, description, props table, and the inherited-attributes note.
172	pub fn format_component(component: &oxc_react_docgen_core::types::ComponentEntry) -> Vec<String> {
173	    use comfy_table::{Attribute, Cell, Color, ContentArrangement, Table};
174	    use owo_colors::OwoColorize;
175	
176	    let mut lines = vec![
177	        String::new(),
178	        format!("  {}  {}", component.display_name.bold(), component.file_path.to_string().dimmed()),
179	        format!("  {}", "─".repeat(70).dimmed()),
180	    ];
181	    if !component.description.is_empty() {
182	        lines.push(String::new());
183	        lines.push(format!("  {}", component.description));
184	    }
185	    lines.push(String::new());
186	    lines.push(format!("  {} ({})", "Props".bold(), component.props.len()));
187	    lines.push(String::new());
188	
189	    let mut table = Table::new();
190	    table.set_content_arrangement(ContentArrangement::Dynamic);
191	    table.set_header(vec![
192	        Cell::new("Prop").add_attribute(Attribute::Bold),
193	        Cell::new("Type").add_attribute(Attribute::Bold),
194	        Cell::new("Req").add_attribute(Attribute::Bold),
195	        Cell::new("Default").add_attribute(Attribute::Bold),
196	        Cell::new("From").add_attribute(Attribute::Bold),
197	    ]);
198	    for prop in component.props.values() {
199	        let req_str = if prop.required { "✓".to_string() } else { "–".to_string() };
200	        let default_str = prop.default_value.as_ref().map(|d| d.value.clone()).unwrap_or_else(|| "–".into());
201	        let from_str = prop.parent.as_ref().map(|p| p.name.clone()).unwrap_or_default();
202	
203	        table.add_row(vec![
204	            Cell::new(&prop.name).fg(Color::White),
205	            Cell::new(prop.prop_type.raw_string()).fg(Color::Cyan),
206	            Cell::new(&req_str),
207	            Cell::new(&default_str).fg(Color::DarkGrey),
208	            Cell::new(&from_str).fg(Color::DarkGrey),
209	        ]);
210	    }
211	    lines.extend(table.to_string().lines().map(|line| format!("  {line}")));
212	
213	    if !component.notable_inherited.is_empty() {
214	        lines.push(String::new());
215	        for layer in &component.inheritance {
216	            let element_note = layer.html_element.as_ref().map(|e| format!(" (<{e}>)")).unwrap_or_default();
217	            lines.push(format!("  {} {}{}", "↳".dimmed(), layer.type_name.dimmed(), element_note.dimmed()));
218	        }
219	        let notable_names: Vec<&str> = component.notable_inherited.keys().map(|s| s.as_str()).collect();
220	        lines.push(format!("    Notable: {}", notable_names.join("  ").dimmed()));
221	    }
222	    lines.push(String::new());
223	    lines
224	}
