5	/// The JSON-facing shape of `docgen.config.ts`'s default export.
6	///
7	/// A deliberate subset of `PipelineOptions` — everything except the fields that
8	/// need complex map/object values (`extraPaths`, `knownTypeOverrides`), which
9	/// aren't supported via config file yet. `deny_unknown_fields` means a config
10	/// using one of those (or a typo'd key) gets a clear error naming the field, not
11	/// a silently-ignored setting — same reasoning as this module's existing "found
12	/// but unsupported" hard error above.
13	#[derive(Debug, Default, Deserialize)]
14	#[serde(rename_all = "camelCase", deny_unknown_fields)]
15	struct DocgenConfigSchema {
16	    src_dirs: Option<Vec<String>>,
17	    exclude_patterns: Option<Vec<String>>,
18	    exclude_prefixes: Option<Vec<String>>,
19	    react_version: Option<String>,
20	    cross_package: Option<bool>,
21	    pandacss_outdir: Option<String>,
22	    variant_functions: Option<Vec<String>>,
23	    html_attributes: Option<String>,
24	    tsconfig_path: Option<String>,
25	    vanilla_extract: Option<bool>,
26	    cache_dir: Option<String>,
27	    extra_builtins: Option<Vec<String>>,
28	}
29	
30	impl DocgenConfigSchema {
31	    /// `Err` names the bad `reactVersion` value — a typo must not silently
32	    /// fall back to react19 (non-negotiable #6: never fail silently).
33	    fn into_pipeline_options(self) -> Result<PipelineOptions, String> {
34	        let mut opts = PipelineOptions::default();
35	        if let Some(dirs) = self.src_dirs {
36	            opts.src_dirs = dirs.into_iter().map(Into::into).collect();
37	        }
38	        if let Some(patterns) = self.exclude_patterns {
39	            opts.exclude_patterns = patterns;
40	        }
41	        if let Some(prefixes) = self.exclude_prefixes {
42	            opts.exclude_prefixes = prefixes;
43	        }
44	        if let Some(v) = self.react_version.as_deref() {
45	            opts.react_version = oxc_react_docgen_core::react_types::parse_react_version(v)
46	                .map_err(|bad| format!("reactVersion is '{bad}', expected \"react18\" or \"react19\""))?;
47	        }
48	        if let Some(cross_package) = self.cross_package {
49	            opts.cross_package = cross_package;
50	        }
51	        if let Some(dir) = self.pandacss_outdir {
52	            opts.pandacss_outdir = Some(dir.into());
53	        }
54	        if let Some(fns) = self.variant_functions {
55	            opts.variant_functions = fns;
56	        }
57	        if let Some(mode) = self.html_attributes.as_deref() {
58	            opts.html_attributes = match mode {
59	                "full" => HtmlAttributeMode::Full,
60	                "none" => HtmlAttributeMode::None,
61	                _ => HtmlAttributeMode::Curated,
62	            };
63	        }
64	        if let Some(path) = self.tsconfig_path {
65	            opts.tsconfig_path = Some(path.into());
66	        }
67	        if let Some(vanilla_extract) = self.vanilla_extract {
68	            opts.vanilla_extract = vanilla_extract;
69	        }
70	        if let Some(dir) = self.cache_dir {
71	            opts.cache_dir = Some(dir.into());
72	        }
73	        if let Some(names) = self.extra_builtins {
74	            opts.extra_builtins = names.into_iter().map(Into::into).collect();
75	        }
76	        Ok(opts)
77	    }
78	}
