80	/// Find and load docgen.config.ts, walking up from start_dir to workspace root.
81	///
82	/// Returns `Ok(None)` when no config file exists anywhere between `start_dir` and the
83	/// workspace root — callers fall back to [`PipelineOptions::default`]. Returns `Err` when
84	/// a config file IS found but can't be honored; see [`try_load_config`].
85	pub fn load_config_file(start_dir: &std::path::Path) -> Result<Option<PipelineOptions>> {
86	    let mut dir = start_dir;
87	    loop {
88	        let candidate = dir.join("docgen.config.ts");
89	        if candidate.exists() {
90	            return try_load_config(&candidate);
91	        }
92	        // Stop at workspace root signals
93	        for signal in &["pnpm-workspace.yaml", "turbo.json", ".moon/workspace.yml"] {
94	            if dir.join(signal).exists() {
95	                return Ok(None);
96	            }
97	        }
98	        let Some(parent) = dir.parent() else { return Ok(None) };
99	        dir = parent;
100	    }
101	}
