103	/// Execute `docgen.config.ts` at `path` and map its default export onto
104	/// [`PipelineOptions`].
105	///
106	/// A config file that fails to evaluate, or evaluates to something that doesn't
107	/// match [`DocgenConfigSchema`] (a typo'd key, wrong value type, or a field this
108	/// module doesn't support yet), is a hard error rather than silently falling back
109	/// to defaults — CLAUDE.md non-negotiable #6: never fail silently. A
110	/// config a user explicitly wrote getting quietly ignored is a plausible-looking
111	/// but wrong result forever.
112	pub fn try_load_config(path: &std::path::Path) -> Result<Option<PipelineOptions>> {
113	    use std::io::Write;
114	
115	    // Canonicalize before passing to node — command.current_dir(dir) below
116	    // changes the working directory to the config's parent, and a *relative*
117	    // __DOCGEN_CONFIG_PATH would then resolve against that new cwd instead of
118	    // the cwd this path was originally relative to (e.g. `--config
119	    // plain/docgen.config.ts` would fail with ERR_MODULE_NOT_FOUND even though
120	    // the file exists). Falls back to the original path if canonicalization
121	    // fails (e.g. the file doesn't exist) so the resulting "file not found"
122	    // error still names the path the user actually typed.
123	    let path = &path.canonicalize().unwrap_or_else(|_| path.to_path_buf());
124	
125	    // Pass the config path via environment variable to avoid any path content
126	    // being interpreted as JavaScript (command injection via crafted filenames).
127	    let script = "import { pathToFileURL } from 'node:url';\
128	        const p = process.env.__DOCGEN_CONFIG_PATH;\
129	        const m = await import(pathToFileURL(p).href);\
130	        process.stdout.write(JSON.stringify(m.default ?? m));";
131	
132	    let mut command = std::process::Command::new("node");
133	    command
134	        .args(["--input-type=module"])
135	        .env("NODE_OPTIONS", "--import=tsx/esm")
136	        .env("__DOCGEN_CONFIG_PATH", path)
137	        .stdin(std::process::Stdio::piped())
138	        .stdout(std::process::Stdio::piped())
139	        .stderr(std::process::Stdio::piped());
140	    // Resolve `tsx` (and anything the config file itself imports) relative to the
141	    // config file's own directory, not wherever the CLI happened to be invoked
142	    // from — matters for `--config ../other-project/docgen.config.ts` pointing
143	    // outside the current project, and for a project whose `tsx` devDependency
144	    // isn't hoisted to whatever the caller's own cwd happens to be.
145	    if let Some(dir) = path.parent() {
146	        command.current_dir(dir);
147	    }
148	    let mut child = command
149	        .spawn()
150	        .into_diagnostic()
151	        .wrap_err("Failed to spawn node to evaluate docgen.config.ts — is node installed and on PATH?")?;
152	
153	    // drop(stdin) below signals EOF so node's read finishes.
154	    let mut stdin =
155	        child.stdin.take().ok_or_else(|| miette::miette!("failed to open stdin for the node subprocess"))?;
156	    stdin.write_all(script.as_bytes()).into_diagnostic()?;
157	    drop(stdin);
158	
159	    let output = child.wait_with_output().into_diagnostic()?;
160	
161	    if !output.status.success() {
162	        let stderr = String::from_utf8_lossy(&output.stderr);
163	        return Err(miette::miette!(
164	            help = "Check docgen.config.ts for syntax errors, or remove it to use defaults.",
165	            "docgen.config.ts at {} failed to evaluate ({}):\n{}",
166	            path.display(),
167	            output.status,
168	            stderr.trim(),
169	        ));
170	    }
171	
172	    let schema: DocgenConfigSchema = serde_json::from_slice(&output.stdout).map_err(|e| {
173	        miette::miette!(
174	            help = "Check docgen.config.ts's exported fields against the supported schema \
175	                    (srcDirs, excludePatterns, excludePrefixes, reactVersion, crossPackage, \
176	                    pandacssOutdir, variantFunctions, htmlAttributes, tsconfigPath, \
177	                    vanillaExtract, cacheDir, extraBuiltins).",
178	            "docgen.config.ts at {} doesn't match the expected shape: {}",
179	            path.display(),
180	            e,
181	        )
182	    })?;
183	
184	    let opts =
185	        schema.into_pipeline_options().map_err(|e| miette::miette!("docgen.config.ts at {}: {}", path.display(), e))?;
186	    Ok(Some(opts))
187	}
