189	/// CLI-flag overrides for [`build_options`], bundled to stay under this crate's
190	/// `too-many-arguments-threshold` of 6 (see `.clippy.toml`).
191	pub struct BuildOptionsArgs<'a> {
192	    pub src: &'a [String],
193	    pub no_cross_package: bool,
194	    pub react_version: Option<&'a str>,
195	    pub cache_dir: Option<&'a str>,
196	    pub html_attributes: Option<&'a str>,
197	    pub config_path: Option<&'a str>,
198	    pub extra_builtins: &'a [String],
199	}
200	
201	pub fn build_options(args: BuildOptionsArgs) -> Result<PipelineOptions> {
202	    let cwd = std::env::current_dir().unwrap_or_default();
203	    let config_override = match args.config_path {
204	        Some(p) => try_load_config(std::path::Path::new(p))?,
205	        None => load_config_file(&cwd)?,
206	    };
207	
208	    let mut opts = config_override.unwrap_or_default();
209	
210	    if !args.src.is_empty() {
211	        opts.src_dirs = args.src.iter().map(|s| s.into()).collect();
212	    }
213	    if args.no_cross_package {
214	        opts.cross_package = false;
215	    }
216	    if let Some(v) = args.react_version {
217	        opts.react_version = oxc_react_docgen_core::react_types::parse_react_version(v).map_err(|bad| {
218	            miette::miette!(
219	                help = "Expected \"react18\" or \"react19\".",
220	                "--react-version is '{}', which isn't a recognized value",
221	                bad
222	            )
223	        })?;
224	    }
225	    if let Some(dir) = args.cache_dir {
226	        opts.cache_dir = Some(dir.into());
227	    }
228	    if let Some(mode) = args.html_attributes {
229	        opts.html_attributes = match mode {
230	            "full" => oxc_react_docgen_core::pipeline::HtmlAttributeMode::Full,
231	            "none" => oxc_react_docgen_core::pipeline::HtmlAttributeMode::None,
232	            _ => oxc_react_docgen_core::pipeline::HtmlAttributeMode::Curated,
233	        };
234	    }
235	    if !args.extra_builtins.is_empty() {
236	        opts.extra_builtins = args.extra_builtins.iter().map(Into::into).collect();
237	    }
238	
239	    Ok(opts)
240	}
