338	        // --config path whose parent directory differs from the process's
339	        // actual cwd failed with ERR_MODULE_NOT_FOUND even though the file
340	        // existed. Constructs a relative path without mutating the process's
341	        // actual cwd (cargo test's default cwd for this crate is
342	        // CARGO_MANIFEST_DIR, i.e. crates/cli — mirrors how `validate_dir`
343	        // above is itself expressed relative to that same cwd) so this stays
344	        // safe under parallel test execution.
345	        let validate_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../apps/validate");
346	        let tmp = tempfile::TempDir::new_in(&validate_dir).unwrap();
347	        let config_path = tmp.path().join("docgen.config.ts");
348	        std::fs::write(&config_path, "export default { srcDirs: [\"src/components\"] };\n").unwrap();
349	
