368	    #[test]
369	    fn config_path_containing_quotes_and_an_exit_payload_is_not_interpreted_as_javascript() {
370	        let validate_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../apps/validate");
371	        let tmp = tempfile::TempDir::new_in(&validate_dir).unwrap();
372	        // Combines a single quote, a double quote, and the exact "break out of
373	        // a string literal and call process.exit(1)" payload AC-001 names —
374	        // if try_load_config ever regressed to string-concatenating this path
375	        // into the script source, node would execute process.exit(1) before
376	        // ever importing the real config, and this test would see the wrong
377	        // exit path (an Err, or Ok with the wrong content) instead of a clean
378	        // Ok(Some(..)) reflecting the config file's real content.
379	        let dangerous_name = "evil'\"');process.exit(1);('dir";
380	        let dangerous_dir = tmp.path().join(dangerous_name);
381	        std::fs::create_dir_all(&dangerous_dir).expect("create directory with a dangerous name");
382	        let config_path = dangerous_dir.join("docgen.config.ts");
383	        std::fs::write(&config_path, "export default { srcDirs: [\"src/components\"] };\n").unwrap();
384	
385	        let opts = try_load_config(&config_path)
386	            .expect("a dangerous path must not be interpreted as JavaScript — no injected exit, no eval failure")
387	            .expect("expected Some(PipelineOptions), proving the real config content was evaluated");
388	        assert_eq!(
389	            opts.src_dirs,
390	            vec![camino::Utf8PathBuf::from("src/components")],
391	            "expected the actual config content, not something an injected statement could have produced"
392	        );
393	    }
