395	    #[test]
396	    fn try_load_config_surfaces_the_real_syntax_error_not_just_an_exit_status() {
397	        // Adversarial review finding: node/tsx's stderr was sent to
398	        // Stdio::null(), so a config file that failed to evaluate produced a
399	        // generic "failed to evaluate (exit status: 1)" with the actual
400	        // syntax error/stack trace thrown away — the one piece of
401	        // information that would actually tell the user what's wrong.
402	        let validate_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../apps/validate");
403	        let tmp = tempfile::TempDir::new_in(&validate_dir).unwrap();
404	        let config_path = tmp.path().join("docgen.config.ts");
405	        std::fs::write(&config_path, "export default {{{{ this is not valid javascript").unwrap();
406	
407	        let err = try_load_config(&config_path).expect_err("a real syntax error should fail to evaluate");
408	        let message = format!("{err:?}");
409	        // This repo's apps/validate uses tsx's esbuild-based transform, which
410	        // reports "ERROR: Expected identifier..."; a native TS-stripping
411	        // toolchain would instead say "SyntaxError" — accept either so this
412	        // isn't pinned to one specific transpiler's exact wording.
413	        assert!(
414	            message.contains("Expected identifier") || message.contains("SyntaxError"),
415	            "expected the real node/tsx error output in the message, got: {message}"
416	        );
417	    }
