71	/// RDT's type-name convention for literal unions: `{"name": "enum", "value": [...]}`
72	/// instead of inlining the literal text into `type.name` as a plain string. Lets
73	/// prop-table renderers that pattern-match `type.name === "enum"` (a common
74	/// Storybook addon integration point) show a `<select>` control for the most
75	/// common, most curated props in any design system (variant, size, color…).
76	fn rdt_type_json(prop_type: &oxc_react_docgen_core::types::PropType) -> serde_json::Value {
77	    use oxc_react_docgen_core::types::PropType;
78	
79	    if prop_type.is_literal_union() {
80	        let values: Vec<serde_json::Value> = match prop_type {
81	            PropType::Union(members) => members.iter().map(|m| serde_json::json!({"value": m.raw_string()})).collect(),
82	            PropType::LiteralUnion { members, .. } => {
83	                members.iter().map(|m| serde_json::json!({"value": format!("\"{m}\"")})).collect()
84	            }
85	            _ => vec![],
86	        };
87	        return serde_json::json!({ "name": "enum", "value": values });
88	    }
89	    serde_json::json!({ "name": prop_type.raw_string() })
90	}
91	
92	/// RDT's default `skipChildrenPropWithoutDoc`: an undocumented `children` says nothing a
93	/// prop table can show, so RDT never emits it. Canonical output keeps it.
94	fn rdt_omits(prop: &oxc_react_docgen_core::types::ParsedProp) -> bool {
95	    prop.name == "children" && prop.description.is_empty()
96	}
97	
98	/// `methods` is always `[]` — this tool doesn't extract class methods, and RDT
99	/// consumers (Storybook's docgen addon) only ever read it for class components.
100	pub fn serialize_rdt(output: &oxc_react_docgen_core::types::ExtractionOutput) -> String {
101	    let mut map = serde_json::Map::new();
102	    for (name, entry) in &output.components {
103	        let props: serde_json::Map<String, serde_json::Value> = entry
104	            .props
105	            .iter()
106	            .filter(|(_, prop)| !rdt_omits(prop))
107	            .map(|(k, prop)| {
108	                let obj = serde_json::json!({
109	                    "name": prop.name,
110	                    "type": rdt_type_json(&prop.prop_type),
111	                    "required": prop.required,
112	                    "defaultValue": prop.default_value.as_ref().map(|d| serde_json::json!({"value": d.value, "computed": d.computed})),
113	                    "description": prop.description,
114	                    "parent": prop.parent.as_ref().map(|p| serde_json::json!({"name": p.name, "fileName": p.file_name})),
115	                });
116	                (k.clone(), obj)
117	            })
118	            .collect();
119	        map.insert(
120	            name.clone(),
121	            serde_json::json!({
122	                "displayName": entry.display_name,
123	                "props": serde_json::Value::Object(props),
124	                "description": entry.description,
125	                "methods": [],
126	                "tags": entry.tags,
127	                "composes": entry.composes,
128	            }),
129	        );
130	    }
131	    serde_json::to_string_pretty(&serde_json::Value::Object(map)).unwrap_or_default()
132	}
