134	pub fn serialize_storybook(output: &oxc_react_docgen_core::types::ExtractionOutput) -> String {
135	    let mut map = serde_json::Map::new();
136	    for (name, entry) in &output.components {
137	        let props: serde_json::Map<String, serde_json::Value> = entry
138	            .props
139	            .iter()
140	            .map(|(k, prop)| {
141	                let obj = serde_json::json!({
142	                    "name": prop.name,
143	                    "type": { "name": prop.prop_type.raw_string() },
144	                    "required": prop.required,
145	                    "defaultValue": prop.default_value.as_ref().map(|d| serde_json::json!({"value": d.value})),
146	                    "description": prop.description,
147	                });
148	                (k.clone(), obj)
149	            })
150	            .collect();
151	        map.insert(
152	            name.clone(),
153	            serde_json::json!({
154	                "displayName": entry.display_name,
155	                "props": serde_json::Value::Object(props),
156	                "description": entry.description,
157	                "methods": [],
158	            }),
159	        );
160	    }
161	    serde_json::to_string_pretty(&serde_json::Value::Object(map)).unwrap_or_default()
162	}
