14	        cache_dir: None,
15	        html_attributes: None,
16	        config_path,
17	        extra_builtins: &[],
18	    })?;
19	    let output = oxc_react_docgen_core::pipeline::extract(&options);
20	
21	    if args.json {
22	        println!("{}", serde_json::to_string(&output.diagnostics).into_diagnostic()?);
23	    } else if !quiet {
24	        print_summary(&output, quiet);
25	        print_diagnostics(&output.diagnostics);
26	    }
27	
28	    Ok(output.exit_code(args.strict))
29	}
