1	//! LSP (Language Server Protocol) command scaffold for oxc-react-docgen.
2	//!
3	//! Provides IDE hover and component prop documentation in editors (VS Code, Neovim, Helix).
4	
5	use std::io::{self, BufRead, Read, Write};
6	
7	use miette::Result;
8	
9	/// Cap on a single LSP frame's declared `Content-Length`, checked *before*
10	/// `vec![0u8; len]` allocates — `Content-Length` is client-controlled input
11	/// with no upper bound of its own.
12	const MAX_LSP_MESSAGE_BYTES: usize = 16 * 1024 * 1024; // 16 MiB
13	
14	/// Reject an oversized frame before its receive buffer is allocated.
15	fn check_content_length(len: usize) -> Result<()> {
16	    if len > MAX_LSP_MESSAGE_BYTES {
17	        tracing::error!(
18	            "LSP frame declared Content-Length {len} bytes, exceeding the {MAX_LSP_MESSAGE_BYTES}-byte cap; closing connection"
19	        );
20	        return Err(miette::miette!(
21	            "LSP frame declared Content-Length {len} bytes, exceeding the {MAX_LSP_MESSAGE_BYTES}-byte cap"
22	        ));
23	    }
24	    Ok(())
25	}
26	
27	/// Reads header lines up to the blank-line terminator and returns the parsed
28	/// `Content-Length`, if any.
29	///
30	/// `Err(())` means the stream ended before any header line was read at all —
31	/// a normal, expected way for a client to close the connection.
32	/// `Ok(None)` means a header block *was* read (the loop reached the blank
33	/// line) but it contained no usable `Content-Length` — missing header or an
34	/// unparsable value. That body's byte length is unknowable, so the caller
35	/// must not keep reading from the stream as if nothing happened: doing so
36	/// desyncs every subsequent frame, since the unconsumed body bytes get read
37	/// as the start of the *next* header block.
38	fn read_content_length<R: BufRead>(reader: &mut R) -> Result<Option<usize>, ()> {
39	    let mut content_length: Option<usize> = None;
40	    let mut line = String::new();
41	
42	    loop {
43	        line.clear();
44	        if reader.read_line(&mut line).unwrap_or(0) == 0 {
45	            return Err(());
46	        }
47	        if line == "\r\n" || line == "\n" {
48	            break;
49	        }
50	        if let Some(header) = line.strip_prefix("Content-Length: ") {
51	            content_length = header.trim().parse().ok();
52	        }
53	    }
54	
55	    Ok(content_length)
56	}
57	
58	/// The `initialize` response's `result` payload — factored out so capability
59	/// advertisement is testable without driving the stdin/stdout loop.
60	fn initialize_result() -> serde_json::Value {
61	    serde_json::json!({
62	        "capabilities": {
63	            "textDocumentSync": 1,
64	            // No textDocument/hover handler exists in the method dispatch
65	            // below (it falls into the `_ => {}` catch-all) — advertising
66	            // `true` would make a client's hover request, which carries an
67	            // `id`, hang forever waiting for a response that never comes.
68	            "hoverProvider": false
69	        },
70	        "serverInfo": {
71	            "name": "oxc-react-docgen-lsp",
72	            "version": env!("CARGO_PKG_VERSION")
73	        }
74	    })
75	}
76	
77	pub fn cmd_lsp() -> Result<()> {
78	    let stdin = io::stdin();
79	    let mut stdin_lock = stdin.lock();
80	    let stdout = io::stdout();
81	    let mut stdout_lock = stdout.lock();
82	
83	    loop {
84	        let content_length = match read_content_length(&mut stdin_lock) {
85	            Err(()) => return Ok(()), // EOF
86	            Ok(v) => v,
87	        };
88	
89	        let Some(len) = content_length else {
90	            tracing::error!(
91	                "LSP frame's header block had no usable Content-Length; closing connection to avoid a desynced stream"
92	            );
93	            return Err(miette::miette!("received an LSP frame without a usable Content-Length header"));
94	        };
95	
96	        check_content_length(len)?;
97	
98	        let mut buf = vec![0u8; len];
99	        if stdin_lock.read_exact(&mut buf).is_err() {
100	            return Ok(());
101	        }
102	
103	        let Ok(msg) = serde_json::from_slice::<serde_json::Value>(&buf) else {
104	            continue;
105	        };
106	
107	        if let Some(method) = msg["method"].as_str() {
108	            let id = msg.get("id");
109	            match method {
110	                "initialize" => {
111	                    if let Some(id) = id {
112	                        let response = serde_json::json!({
113	                            "jsonrpc": "2.0",
114	                            "id": id,
115	                            "result": initialize_result()
116	                        });
117	                        send_response(&mut stdout_lock, &response);
118	                    }
119	                }
120	                "shutdown" => {
121	                    if let Some(id) = id {
122	                        let response = serde_json::json!({
123	                            "jsonrpc": "2.0",
124	                            "id": id,
125	                            "result": null
126	                        });
127	                        send_response(&mut stdout_lock, &response);
128	                    }
129	                }
130	                "exit" => break,
131	                _ => {}
132	            }
133	        }
134	    }
135	
136	    Ok(())
137	}
138	
139	fn send_response<W: Write>(out: &mut W, response: &serde_json::Value) {
140	    if let Ok(json) = serde_json::to_string(response) {
141	        let header = format!("Content-Length: {}\r\n\r\n", json.len());
142	        if let Err(e) =
143	            out.write_all(header.as_bytes()).and_then(|()| out.write_all(json.as_bytes())).and_then(|()| out.flush())
144	        {
145	            // A broken client pipe otherwise leaves this response silently
146	            // undelivered with zero trace anywhere — stderr is the safe
147	            // channel here for the same reason `check_content_length` already
148	            // uses it: stdout is reserved exclusively for Content-Length-framed
149	            // messages.
150	            tracing::error!("Failed to write LSP response frame: {e}");
151	        }
152	    }
153	}
154	
155	#[cfg(test)]
156	mod tests {
157	    use super::*;
158	
159	    #[test]
160	    fn test_oversized_content_length_is_rejected() {
161	        let result = check_content_length(MAX_LSP_MESSAGE_BYTES + 1);
162	        assert!(result.is_err(), "expected a Content-Length past the cap to be rejected, got {:?}", result);
163	    }
164	
165	    #[test]
166	    fn test_content_length_at_cap_is_accepted() {
167	        let result = check_content_length(MAX_LSP_MESSAGE_BYTES);
168	        assert!(result.is_ok(), "expected a Content-Length exactly at the cap to be accepted, got {:?}", result);
169	    }
170	
171	    #[test]
172	    fn test_hover_not_advertised_without_a_handler() {
173	        let result = initialize_result();
174	        assert_eq!(
175	            result["capabilities"]["hoverProvider"],
176	            serde_json::json!(false),
177	            "hoverProvider must stay false until a textDocument/hover handler exists — a client hover \
178	             request carries an id and nothing replies to it today"
179	        );
180	    }
181	
182	    #[test]
183	    fn test_headerless_frame_is_reported_as_malformed_not_eof() {
184	        // Blank line reached with no Content-Length header at all — the
185	        // pre-fix code left `content_length: None` and `continue`d straight
186	        // past the body that frame's sender still wrote, permanently
187	        // desyncing every header block read afterward.
188	        let mut reader = std::io::Cursor::new(b"X-Some-Other-Header: value\r\n\r\n".to_vec());
189	        assert_eq!(read_content_length(&mut reader), Ok(None));
190	    }
191	
192	    #[test]
193	    fn test_unparsable_content_length_is_reported_as_malformed() {
194	        let mut reader = std::io::Cursor::new(b"Content-Length: not-a-number\r\n\r\n".to_vec());
195	        assert_eq!(read_content_length(&mut reader), Ok(None));
196	    }
197	
198	    #[test]
199	    fn test_true_stream_eof_is_distinct_from_a_malformed_header_block() {
200	        // No bytes at all (client closed the connection) is a normal,
201	        // expected way to end the loop — must not be conflated with a
202	        // header block that was read but had no usable Content-Length.
203	        let mut reader = std::io::Cursor::new(Vec::new());
204	        assert_eq!(read_content_length(&mut reader), Err(()));
205	    }
206	
207	    // ── SPEC-CLI-001c AC-005b: a connection that closes after one or more
208	    // complete header lines but BEFORE the blank-line terminator is reached
209	    // is currently treated identically to a clean EOF (Err(())), not as a
210	    // malformed header block (Ok(None)) — the blank line never arrives, so
211	    // read_line's next call returns 0 bytes while still inside the header
212	    // loop, same as AC-005's true-EOF case.
213	
214	    #[test]
215	    fn test_connection_closed_mid_header_before_blank_line_is_treated_as_eof() {
216	        let mut reader = std::io::Cursor::new(b"Content-Length: 10\r\n".to_vec());
217	        assert_eq!(read_content_length(&mut reader), Err(()));
218	    }
219	
220	    // ── SPEC-CLI-001c AC-005d: non-UTF8 bytes in the header block map to the
221	    // same Err(()) EOF-like outcome, since read_line's io::Error is folded
222	    // into unwrap_or(0) — indistinguishable from a clean disconnect.
223	
224	    #[test]
225	    fn test_non_utf8_header_bytes_are_treated_as_eof() {
226	        let mut reader = std::io::Cursor::new(b"Content-Length: 10\xFF\r\n\r\n".to_vec());
227	        assert_eq!(read_content_length(&mut reader), Err(()));
228	    }
229	
230	    // ── A broken client pipe (or any writer failure) during send_response
231	    // must not vanish silently — see the fix's doc comment. A failing writer
232	    // proves send_response doesn't panic; a capturing tracing subscriber
233	    // proves the failure actually reaches the log, not just "doesn't crash."
234	
235	    struct FailingWriter;
236	
237	    impl Write for FailingWriter {
238	        fn write(&mut self, _buf: &[u8]) -> std::io::Result<usize> {
239	            Err(std::io::Error::new(std::io::ErrorKind::BrokenPipe, "simulated broken pipe"))
240	        }
241	        fn flush(&mut self) -> std::io::Result<()> {
242	            Err(std::io::Error::new(std::io::ErrorKind::BrokenPipe, "simulated broken pipe"))
243	        }
244	    }
245	
246	    #[derive(Clone, Default)]
247	    struct CapturedLogs(std::sync::Arc<std::sync::Mutex<Vec<u8>>>);
248	
249	    impl Write for CapturedLogs {
250	        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
251	            self.0.lock().unwrap_or_else(|p| p.into_inner()).extend_from_slice(buf);
252	            Ok(buf.len())
253	        }
254	        fn flush(&mut self) -> std::io::Result<()> {
255	            Ok(())
256	        }
257	    }
258	
259	    #[test]
260	    fn send_response_write_failure_does_not_panic_and_is_logged() {
261	        let captured = CapturedLogs::default();
262	        let captured_for_writer = captured.clone();
263	        let subscriber = tracing_subscriber::fmt()
264	            .with_writer(move || captured_for_writer.clone())
265	            .with_ansi(false)
266	            .without_time()
267	            .finish();
268	
269	        tracing::subscriber::with_default(subscriber, || {
270	            let mut writer = FailingWriter;
271	            send_response(&mut writer, &serde_json::json!({"jsonrpc": "2.0", "id": 1, "result": null}));
272	        });
273	
274	        let logged = String::from_utf8(captured.0.lock().unwrap_or_else(|p| p.into_inner()).clone()).unwrap();
275	        assert!(
276	            logged.contains("Failed to write LSP response frame"),
277	            "expected the write failure to be logged, got {logged:?}"
278	        );
279	        assert!(
280	            logged.contains("simulated broken pipe"),
281	            "expected the underlying io::Error to be included, got {logged:?}"
282	        );
283	    }
284	
285	    #[test]
286	    fn send_response_succeeds_normally_with_a_working_writer() {
287	        // Regression guard: the fix must not change the success path's
288	        // behavior — a working writer still receives the full framed response.
289	        let mut buf: Vec<u8> = Vec::new();
290	        send_response(&mut buf, &serde_json::json!({"jsonrpc": "2.0", "id": 1, "result": null}));
291	        let written = String::from_utf8(buf).unwrap();
292	        assert!(written.starts_with("Content-Length:"), "expected a framed response, got {written:?}");
293	        assert!(written.contains("\"result\":null"), "expected the real response body, got {written:?}");
294	    }
295	}
